        addSampleCoordinates(tileAndUv, sampleDatas[0]);
    #else
        getOctreeLeafSampleDatas(nodeData, traversalData.octreeCoords, sampleDatas);
        addSampleCoordinates(tileAndUv, sampleDatas[0]);
        addSampleCoordinates(tileAndUv, sampleDatas[1]);
    #endif
